<script setup lang="ts">
import {ref,onMounted} from 'vue';import axios from 'axios';import {RouterLink} from 'vue-router';
interface Order{id:number;productId:number;title:string;price:number;status:string;buyer:string;seller:string;role:string;createdAt:string}
const orders=ref<Order[]>([]),error=ref(''),busy=ref(false),more=ref(false);
const labels:Record<string,string>={RESERVED:'待线下交接',COMPLETED:'已完成',CANCELLED:'已取消'};
async function load(append=false){try{const {data}=await axios.get('/api/orders',{params:{before:append?orders.value.at(-1)?.id:0}});orders.value=append?[...orders.value,...data]:data;more.value=data.length===30;}catch{error.value='订单加载失败，请重试';}}
async function change(id:number,action:string){if(!confirm(action==='complete'?'确认已收到商品并完成交易？':'确认取消订单并重新上架商品？'))return;busy.value=true;error.value='';try{const token=(await axios.get('/api/auth/csrf')).data.token;await axios.post('/api/orders/'+id+'/'+action,null,{headers:{'X-XSRF-TOKEN':token}});await load();}catch{error.value='操作失败，订单状态可能已更新，请刷新重试';}finally{busy.value=false;}}
onMounted(()=>load());
</script><template><section class="orders"><p>SDU / MY TRADES</p><h1>我的交易</h1><span>校园线下交接，收货后再确认完成。本页面不处理在线付款。</span><p role="alert">{{error}}</p><button @click="load()">刷新订单</button><p v-if="!orders.length">暂无交易记录。</p><article v-for="o in orders" :key="o.id"><header><RouterLink :to="'/market/'+o.productId">{{o.title}}</RouterLink><strong>¥ {{Number(o.price).toFixed(2)}}</strong><span>{{labels[o.status]}}</span></header><p>{{o.role==='BUYER'?'我买到的':'我卖出的'}} · 买家 {{o.buyer}} / 卖家 {{o.seller}}</p><small>订单 #{{o.id}} · {{o.createdAt}}</small><div v-if="o.status==='RESERVED'"><button v-if="o.role==='BUYER'" :disabled="busy" @click="change(o.id,'complete')">确认收货</button><button :disabled="busy" @click="change(o.id,'cancel')">取消订单</button></div></article><button v-if="more" @click="load(true)">加载更多</button></section></template><style scoped>.orders{flex:1;background:#f6f4ee;color:#293d3b;padding:35px 6%}.orders>p:first-child{font-size:10px;letter-spacing:2px;color:#94744c}h1{font-size:30px;margin:20px 0}.orders>span{font-size:12px;color:#8a806b}article{padding:25px;background:white;border-radius:10px;margin:20px 0}article header{display:flex;gap:25px;align-items:center;flex-wrap:wrap}article header a{font-size:18px;color:#304b49}article header span{font-size:12px;color:#94744c}article p,small{font-size:12px;color:#7a8676}button{padding:10px 18px;background:#304b49;color:white;border:0;border-radius:5px;margin:15px 12px 0 0;cursor:pointer}button:disabled{opacity:.5}article>div{margin-top:10px}</style>
